(987, '1112', 29, 2, '2020-05-02 18:22:20', 14, 1, '阿片类药物引起欣快感是由于作用于', '[{\"c\":\"\\u03b4\\u53d7\\u4f53\",\"a\":\"0\"},{\"c\":\" \\u03b1\\u53d7\\u4f53\",\"a\":\"0\"},{\"c\":\"\\u03ba\\u53d7\\u4f53\",\"a\":\"0\"},{\"c\":\"NMDA\\u53d7\\u4f53\",\"a\":\"0\"},{\"c\":\"\\u03bc\\u53d7\\u4f53\",\"a\":\"1\"}]', 0, 0),
